const input=$json.body??$json;
const dealId=input.deal_id??input.dealId,leadId=input.lead_id??input.leadId,propertyId=input.property_id??input.propertyId;
const response=String(input.response_text??input.seller_response??input.inbound_seller_response??input.inbound_message??'').trim();
const dnc=Boolean(input.dnc||input.do_not_contact||input.opted_out);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const classificationKey=input.event_idempotency_key??input.classification_idempotency_key??input.idempotency_key;
const lower=response.toLowerCase();
let classification='neutral',route='WF-343',reason='Seller response requires normal negotiation handling.';
if(!response){classification='missing_response';route='WF-360';reason='No seller response text was supplied; reconcile the inbound event.'}
else if(/stop|remove me|do not contact|dont contact|don't contact|unsubscribe|wrong number/i.test(lower)){classification='opt_out';route='WF-126';reason='Seller explicitly requested no further contact.'}
else if(/yes|interested|sounds good|deal|let'?s do it|accept|accepted|okay with that/i.test(lower)){classification='positive';route='WF-343';reason='Positive seller response; continue negotiation decision flow.'}
else if(/\$\s?\d|price|offer|counter|would take|need to get/i.test(lower)){classification='counteroffer';route='WF-343';reason='Price/offer language detected; route to negotiation decision.'}
else if(/call me|call|phone|talk/i.test(lower)){classification='call_request';route='WF-343';reason='Seller requested a call; negotiation flow should prepare the next action.'}
else if(/no|not interested|pass|decline|declined|too low/i.test(lower)){classification='rejection';route='WF-345';reason='Seller rejection detected; route to controlled re-engagement.'}
else if(/how|what|when|where|why|can you|tell me/i.test(lower)){classification='question';route='WF-343';reason='Seller question detected; route to negotiation response handling.'}
if(dnc){classification='opt_out';route='WF-126';reason='DNC/opt-out state overrides automated negotiation.'}
else if(blockers.length){classification='blocked';route='WF-126';reason='Operational blockers require controlled human handling.'}
const valid=Boolean(dealId&&leadId&&propertyId&&classificationKey);
const eventKey=classificationKey?\`${classificationKey}:ai-classification:${classification}\`:null;
if(!valid&&classification!=='opt_out'&&classification!=='blocked'){classification='reconcile';route='WF-360';reason='Required identity/idempotency fields are missing.'}
return [{json:{workflow:'WF-370',classification,route,reason,response_text:response,deal_id:dealId,lead_id:leadId,property_id:propertyId,classification_idempotency_key:eventKey,source_event_idempotency_key:classificationKey,dnc,blockers,identity_valid:valid,next_action:route==='WF-343'?'negotiation_decision':route==='WF-345'?'controlled_reengagement':route==='WF-126'?'human_control':'reconcile_inbound_event',audit_event:'ai_seller_response_classification'}}];
